binary.types:
export type Field = { name: string, type: string | Schema, offset: number?, size: number?, count: number?, endian: string?, group: number? }
export type Definition = { fields: {Field}, size: number?, endian: string?, union: boolean?, member: string? }
export type Schema = { name: string, size: number, endian: string, fields: {Field} }
export type Source = { size: number, read: (offset: number, size: number) -> string }
export type Options = { maxBytes: number?, maxDepth: number?, maxWork: number? }
export type Mark = { path: string?, name: string?, offset: number, size: number, raw: string?, group: number?, bookmark: boolean?, foreground: any?, background: any? }
export type Result = { schema: Schema, values: {[string]: any}, fields: {Mark}, original: string, offset: number, size: number }

binaryreader.types:
export type Mark = {offset: number, size: number, name: string, group: number, order: number}
export type Reader = { size: number, little: boolean, marks: {Mark}, read: (number, number) -> string,
 range: (Reader, number, number) -> (), bytes: (Reader, number, number) -> string, uint: (Reader, number, number) -> number,
 delta: (Reader, number, number, number) -> number, mark: (Reader, number, number, string, number?) -> (),
 struct: (Reader, number, string, string, number?) -> number, array: (Reader, number, number, number, number, (number, number) -> ()) -> (),
 cstring: (Reader, number, number?, string, number?) -> string, finish: (Reader) -> () }

mcp/init.types:
export type ServerOptions = { name: string, version: string }
export type ToolDefinition = { name: string, description: string?, inputSchema: any? }
export type ResourceDefinition = { uri: string, name: string?, description: string?, mimeType: string? }
export type PromptDefinition = { name: string, description: string?, arguments: any? }
export type HttpOptions = { host: string?, port: number?, path: string?, allowedOrigins: {string}?, maxMessageBytes: number?, maxConnections: number? }
export type Transport = { host: string, port: number, path: string, stop: (Transport) -> () }
export type Server = { tool: (Server, ToolDefinition, (any) -> any) -> (), resource: (Server, ResourceDefinition, (any) -> any) -> (), prompt: (Server, PromptDefinition, (any) -> any) -> (), use: (Server, any) -> (), dispatch: (Server, any) -> any?, serve_http: (Server, HttpOptions?) -> Transport, stop: (Server) -> () }
